content.query:
let win = SecurityEvent | where TimeGenerated {TimeRange} | where tostring(EventID) in ('4625','4688','4720','4722','4724','4725','4726','4727','4728','4729','4730','4732','4733','4738','4776') and (CommandLine has 'SOC-L2' or TargetUserName startswith 'soc-l2-p02' or TargetUserName startswith 'SOCp15' or TargetUserName startswith 'SOCg15' or MemberName has 'SOCp15') | summarize Eventos = count() by Tabla = 'SecurityEvent (Windows)';
let evt = Event | where TimeGenerated {TimeRange} | where RenderedDescription has 'SOC-L2-P14' | summarize Eventos = count() by Tabla = 'Event (Application)';
let sys = Syslog | where TimeGenerated {TimeRange} | where SyslogMessage has 'SOC-L2-P04' or (ProcessName in ('sshd','su') and SyslogMessage has 'socp04') or (Facility == 'local5' and SyslogMessage has 'soc_l2_p13') or (Facility == 'local6' and SyslogMessage has 'SOC-L2-P11') | summarize Eventos = count() by Tabla = 'Syslog (Linux/Apache/PgSQL)';
let iis = W3CIISLog | where TimeGenerated {TimeRange} | where csUriStem has 'SOC-L2-P12' or csUserAgent has 'SOC-L2-Lab' | summarize Eventos = count() by Tabla = 'W3CIISLog (IIS)';
let app = AppServiceHTTPLogs | where TimeGenerated {TimeRange} | where UserAgent startswith 'SOC-L2-Lab' | summarize Eventos = count() by Tabla = 'AppServiceHTTPLogs';
let kv = AZKVAuditLogs | where TimeGenerated {TimeRange} | where RequestUri has 'soc-l2-p07' or OperationName has 'Secret' | summarize Eventos = count() by Tabla = 'AZKVAuditLogs (Key Vault)';
let aks = AKSAuditAdmin | where TimeGenerated {TimeRange} | where RequestUri has 'soc-l2-p08' | summarize Eventos = count() by Tabla = 'AKSAuditAdmin';
let act = AzureActivity | where TimeGenerated {TimeRange} | where OperationNameValue has 'RUNCOMMAND' or (OperationNameValue has 'tags' and ActivityStatusValue == 'Success') | summarize Eventos = count() by Tabla = 'AzureActivity';
union win, evt, sys, iis, app, kv, aks, act | sort by Eventos desc

let apache = Syslog | where TimeGenerated {TimeRange} | where Facility == 'local6' and SyslogMessage has 'SOC-L2-P11' | summarize Peticiones = count() by Servidor = 'Apache (local6)';
let iis = W3CIISLog | where TimeGenerated {TimeRange} | where csUriStem has 'SOC-L2-P12' or csUserAgent has 'SOC-L2-Lab' | summarize Peticiones = count() by Servidor = 'IIS (W3CIISLog)';
union apache, iis
